"""Envelope encryption for tenant keys (format keymgr-envelope-v1).

A fresh 256-bit data key (DEK) seals the plaintext with AES-256-GCM; the DEK is
then wrapped by the named key version (the key-encryption key, KEK):

* ``AES256`` KEK: the DEK is wrapped with AES-256-GCM (wrap scheme
  ``AES-GCM``);
* ``RSA2048`` KEK: the DEK is wrapped with RSA-OAEP-SHA256
  (``RSA-OAEP-SHA256``).

The envelope is one base64 token whose JSON payload carries only metadata and
wrapped material: ``key_id``, ``version``, the algorithm/schemes, the GCM
nonce/tag/ciphertext, the wrapped DEK and the authenticated AAD. Raw private
keys, data keys and passphrases never enter the envelope; the data key exists
only in process memory for the duration of one call.
"""

import base64
import binascii
import json
import os
from dataclasses import dataclass
from typing import Optional

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding, rsa
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

FORMAT = "keymgr-envelope-v1"

# Content encryption is always AES-256-GCM under the ephemeral data key.
ENC_AES_GCM = "AES-GCM"
# KEK wrap schemes.
WRAP_AES_GCM = "AES-GCM"
WRAP_RSA_OAEP_SHA256 = "RSA-OAEP-SHA256"

_AES256 = "AES256"
_RSA2048 = "RSA2048"
_KEY_LEN = 32
_NONCE_LEN = 12
_TAG_LEN = 16
_RSA_WRAP_LEN = 256  # RSA-2048 OAEP ciphertext length.

_OAEP = padding.OAEP(
    mgf=padding.MGF1(algorithm=hashes.SHA256()),
    algorithm=hashes.SHA256(),
    label=None,
)


class EnvelopeError(ValueError):
    """An envelope request failure (always surfaced as 400)."""


@dataclass(frozen=True)
class OpenedEnvelope:
    """Structurally validated, still-encrypted envelope contents."""

    key_id: str
    version: int
    algorithm: str
    enc: str
    wrap: str
    nonce: bytes
    tag: bytes
    ciphertext: bytes
    wrapped_key: bytes
    wrap_nonce: Optional[bytes]
    aad: bytes


def b64_decode_field(value, field: str) -> bytes:
    """Strictly decode standard base64 (padding required).

    Raises EnvelopeError naming the request field on any non-string or
    non-canonical input.
    """
    if not isinstance(value, str):
        raise EnvelopeError("field %s must be a base64 string" % field)
    if value == "":
        return b""
    try:
        raw = base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field %s is not valid base64" % field
        ) from exc
    return raw


def b64_encode(raw: bytes) -> str:
    """Canonical standard base64 encoding used for every envelope token."""
    return base64.b64encode(raw).decode("ascii")


def _wrap_dek(algorithm: str, kek) -> tuple:
    """Wrap a fresh 32-byte DEK under the KEK. Returns (dek, wk, wrap_nonce)."""
    dek = os.urandom(_KEY_LEN)
    if algorithm == _AES256:
        if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
            raise EnvelopeError("server key material is invalid for AES256")
        wrap_nonce = os.urandom(_NONCE_LEN)
        sealed = AESGCM(bytes(kek)).encrypt(wrap_nonce, dek, None)
        return dek, sealed, wrap_nonce
    if algorithm == _RSA2048:
        if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
            raise EnvelopeError(
                "server key material is invalid for RSA2048"
            )
        sealed = kek.public_key().encrypt(dek, _OAEP)
        return dek, sealed, None
    raise EnvelopeError("unsupported algorithm for envelope: %r" % algorithm)


def _unwrap_dek(opened: "OpenedEnvelope", kek) -> bytes:
    """Recover the DEK from the envelope using the KEK."""
    try:
        if opened.algorithm == _AES256:
            if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
                raise EnvelopeError(
                    "server key material is invalid for AES256"
                )
            if opened.wrap_nonce is None:
                raise InvalidTag("missing wrap nonce")
            return AESGCM(bytes(kek)).decrypt(
                opened.wrap_nonce, opened.wrapped_key, None
            )
        if opened.algorithm == _RSA2048:
            if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
                raise EnvelopeError(
                    "server key material is invalid for RSA2048"
                )
            return kek.decrypt(opened.wrapped_key, _OAEP)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    except ValueError as exc:
        # RSA decryption failures (wrong key/size/padding) land here.
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    raise EnvelopeError(
        "field envelope is tampered or cannot be authenticated"
    )


def encode_envelope(
    *,
    key_id: str,
    version: int,
    algorithm: str,
    kek,
    plaintext: bytes,
    aad: Optional[bytes] = None,
) -> str:
    """Seal plaintext under a fresh data key wrapped by the KEK.

    Returns the opaque base64 envelope token. The KEK is the raw 32-byte key
    for AES256 or a loaded 2048-bit RSA private key for RSA2048 (its public
    component wraps the DEK).
    """
    if aad is None:
        aad = b""
    dek, wrapped_key, wrap_nonce = _wrap_dek(algorithm, kek)
    nonce = os.urandom(_NONCE_LEN)
    sealed = AESGCM(dek).encrypt(nonce, plaintext, aad)
    ciphertext, tag = sealed[:-_TAG_LEN], sealed[-_TAG_LEN:]
    wrap = WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    payload = {
        "format": FORMAT,
        "key_id": key_id,
        "version": version,
        "algorithm": algorithm,
        "enc": ENC_AES_GCM,
        "wrap": wrap,
        "nonce": b64_encode(nonce),
        "tag": b64_encode(tag),
        "ciphertext": b64_encode(ciphertext),
        "wrapped_key": b64_encode(wrapped_key),
        "aad": b64_encode(aad),
    }
    if wrap_nonce is not None:
        payload["wrap_nonce"] = b64_encode(wrap_nonce)
    raw = json.dumps(
        payload, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return b64_encode(raw)


def _require_str(obj: dict, name: str) -> str:
    value = obj.get(name)
    if not isinstance(value, str) or not value:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    return value


def _require_b64(obj: dict, name: str, *, allow_empty: bool = False) -> bytes:
    value = obj.get(name)
    if not isinstance(value, str):
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    if not value and not allow_empty:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    try:
        return base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field envelope has invalid base64 in %s" % name
        ) from exc


def decode_envelope(token: str) -> OpenedEnvelope:
    """Parse and structurally validate an envelope token (no crypto).

    Raises EnvelopeError (surfaced as 400) naming ``field envelope`` for any
    malformed, truncated, tampered-shape or unsupported-format token.
    """
    if not isinstance(token, str) or not token:
        raise EnvelopeError("field envelope must be a non-empty string")
    try:
        raw = base64.b64decode(token.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError("field envelope is not valid base64") from exc
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        ) from exc
    if not isinstance(obj, dict):
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        )
    if obj.get("format") != FORMAT:
        raise EnvelopeError("field envelope format must be %r" % FORMAT)
    key_id = _require_str(obj, "key_id")
    version = obj.get("version")
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 1
    ):
        raise EnvelopeError(
            "field envelope version must be a positive integer"
        )
    algorithm = obj.get("algorithm")
    if algorithm not in (_AES256, _RSA2048):
        raise EnvelopeError(
            "field envelope algorithm must be one of: AES256, RSA2048"
        )
    expected_wrap = (
        WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    )
    if obj.get("enc") != ENC_AES_GCM:
        raise EnvelopeError("field envelope enc must be %r" % ENC_AES_GCM)
    if obj.get("wrap") != expected_wrap:
        raise EnvelopeError(
            "field envelope wrap must be %r for algorithm %s"
            % (expected_wrap, algorithm)
        )
    nonce = _require_b64(obj, "nonce")
    tag = _require_b64(obj, "tag")
    if len(nonce) != _NONCE_LEN:
        raise EnvelopeError("field envelope nonce must be 12 bytes")
    if len(tag) != _TAG_LEN:
        raise EnvelopeError("field envelope tag must be 16 bytes")
    ciphertext = _require_b64(obj, "ciphertext", allow_empty=True)
    wrapped_key = _require_b64(obj, "wrapped_key")
    wrap_nonce = None
    if algorithm == _AES256:
        wrap_nonce = _require_b64(obj, "wrap_nonce")
        if len(wrap_nonce) != _NONCE_LEN:
            raise EnvelopeError(
                "field envelope wrap_nonce must be 12 bytes"
            )
        # AES-GCM of a 32-byte DEK is exactly 48 bytes (32 + 16 tag).
        if len(wrapped_key) != _KEY_LEN + _TAG_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
    else:
        if len(wrapped_key) != _RSA_WRAP_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
        if "wrap_nonce" in obj and obj["wrap_nonce"] is not None:
            raise EnvelopeError(
                "field envelope wrap_nonce must be absent for RSA2048"
            )
    aad = b""
    if "aad" in obj and obj["aad"] is not None:
        aad = _require_b64(obj, "aad", allow_empty=True)
    return OpenedEnvelope(
        key_id=key_id,
        version=version,
        algorithm=algorithm,
        enc=ENC_AES_GCM,
        wrap=expected_wrap,
        nonce=nonce,
        tag=tag,
        ciphertext=ciphertext,
        wrapped_key=wrapped_key,
        wrap_nonce=wrap_nonce,
        aad=aad,
    )


def open_envelope(opened: OpenedEnvelope, kek) -> bytes:
    """Unwrap the data key and decrypt the payload (AES/RSA KEK).

    A wrong key version, a modified nonce/tag/ciphertext/wrapped_key or a
    failed RSA unpadding all fail as one field-naming authentication error;
    the caller separately checks that the request AAD equals the envelope AAD.
    """
    dek = _unwrap_dek(opened, kek)
    try:
        sealed = opened.ciphertext + opened.tag
        return AESGCM(dek).decrypt(opened.nonce, sealed, opened.aad)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc

"""Per-tenant action policies: validation, persistence and enforcement.

A policy document is a list of rules; each rule binds a ``subject`` (the
X-Operator-Id of the caller), a set of ``actions`` and an ``effect`` of
``allow`` or ``deny``. Enforcement, for one (tenant, subject, action):

* a tenant with no document is unrestricted (every action is allowed);
* among the rules whose subject equals the caller and whose actions contain
  the action, any ``deny`` wins over ``allow``;
* if no matching rule exists the action is denied (default deny).

Documents are stored as one JSON file per tenant, written through the same
outbox transaction as key records: the file first lands carrying the audit
event, the ledger append follows, then the marker is cleared; a crash in
between is repaired idempotently on the next open.
"""

import hashlib
import json
import os
import tempfile
import threading
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Iterator, List, Optional

from . import audit as audit_mod
from .audit import AuditEvent, AuditLog, LedgerError

try:  # fcntl is POSIX-only; policy writes still work without it.
    import fcntl
except ImportError:  # pragma: no cover - non-POSIX platforms
    fcntl = None

# Actions a policy rule can govern. These are the same action names the audit
# ledger uses (the management actions policy_* are deliberately not governable).
POLICY_ACTIONS = (
    "create",
    "read",
    "rotate",
    "revoke",
    "import",
    "export",
    "migrate",
    "encrypt",
    "decrypt",
    "sign",
    "verify",
    "audit",
    "list",
)
EFFECTS = ("allow", "deny")
_POLICY_DIR = "policies"


class PolicyError(ValueError):
    """A policy document or rule failed validation (surfaced as 400)."""


@dataclass(frozen=True)
class Rule:
    """One policy rule: an effect on a set of actions for one subject."""

    subject: str
    actions: List[str]
    effect: str

    def to_json(self) -> dict:
        """Serialize to a plain dict; actions are emitted sorted."""
        return {
            "subject": self.subject,
            "actions": list(self.actions),
            "effect": self.effect,
        }

    @classmethod
    def from_json(cls, data: dict) -> "Rule":
        # Documents on disk were validated when written, but validate again
        # on the way in so a hand-edited file can never break enforcement.
        return validate_rule(data)

    def signature(self):
        """Dedup key: same subject/effect with the same unordered action set."""
        return self.subject, self.effect, frozenset(self.actions)


def validate_rule(raw, index: Optional[int] = None) -> Rule:
    """Validate one rule object; raise PolicyError naming the bad field.

    ``index`` prefixes field names with ``rules[i].`` when the rule comes from
    a document; a standalone rule names the bare fields.
    """
    where = "rules[%d]." % index if index is not None else ""

    def err(message: str) -> PolicyError:
        return PolicyError(message)

    if not isinstance(raw, dict):
        raise err("field %s must be an object" % (where.rstrip(".") if index is not None else "rule"))
    known = {"subject", "actions", "effect"}
    unknown = set(raw) - known
    if unknown:
        raise err(
            "unknown field %s%s"
            % (where, sorted(unknown)[0])
        )
    subject = raw.get("subject")
    if not isinstance(subject, str) or not subject:
        raise err("field %ssubject must be a non-empty string" % where)
    effect = raw.get("effect")
    if not isinstance(effect, str) or effect not in EFFECTS:
        raise err(
            "field %seffect must be one of: %s"
            % (where, ", ".join(EFFECTS))
        )
    actions = raw.get("actions")
    if not isinstance(actions, list) or not actions:
        raise err(
            "field %sactions must be a non-empty array" % where
        )
    clean_actions = []
    for action in actions:
        if not isinstance(action, str) or not action:
            raise err(
                "field %sactions must be non-empty strings" % where
            )
        if action not in POLICY_ACTIONS:
            raise err(
                "field %sactions has unknown action %r (allowed: %s)"
                % (where, action, ", ".join(POLICY_ACTIONS))
            )
        if action not in clean_actions:
            # Duplicates within one rule are dropped, not an error: the action
            # set is unordered, so ["read", "read"] carries no extra meaning.
            clean_actions.append(action)
    return Rule(subject=subject, actions=clean_actions, effect=effect)


def validate_rules(raw) -> List[Rule]:
    """Validate a full rules array; [] is valid and means default-deny."""
    if not isinstance(raw, list):
        raise PolicyError("field rules must be an array")
    rules: List[Rule] = []
    seen = set()
    for index, item in enumerate(raw):
        rule = validate_rule(item, index)
        if rule.signature() in seen:
            raise PolicyError(
                "field rules contains a duplicate rule at index %d "
                "(same subject, effect and unordered actions)" % index
            )
        seen.add(rule.signature())
        rules.append(rule)
    return rules


class PolicyStore:
    """File-backed per-tenant policy documents."""

    def __init__(self, data_dir: str, audit_log: Optional[AuditLog] = None) -> None:
        self.data_dir = data_dir
        self.dir_path = os.path.join(data_dir, _POLICY_DIR)
        os.makedirs(self.dir_path, exist_ok=True)
        self.audit = audit_log if audit_log is not None else AuditLog(data_dir)
        self._write_lock = threading.Lock()
        self._recover_pending_events()

    # -- on-disk shape -----------------------------------------------------
    def path_for(self, tenant_id: str) -> str:
        """Public accessor for a tenant's policy document path."""
        return self._path_for(tenant_id)

    def _path_for(self, tenant_id: str) -> str:
        # Tenant ids are free-form strings, so never use them as a filename:
        # key the file by a digest of the tenant instead.
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".json")

    def _lock_path_for(self, tenant_id: str) -> str:
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.dir_path, digest + ".lock")

    @contextmanager
    def tenant_lock(
        self, tenant_id: str, timeout: Optional[float] = None
    ) -> Iterator[None]:
        """Serialize all writes to one tenant's policy across processes.

        Pairs the in-process write lock with an exclusive ``fcntl`` lock on a
        per-tenant sidecar file, so a put/delete/restore/backup in another
        process cannot interleave with this one's read-modify-write. With a
        finite ``timeout`` (idempotent restore) the wait is bounded and raises
        :class:`~keymgr.store.LockTimeout` when it elapses.
        """
        import time as _time

        from .store import LockTimeout

        deadline = None if timeout is None else _time.monotonic() + timeout
        if timeout is None:
            self._write_lock.acquire()
        else:
            if not self._write_lock.acquire(timeout=max(timeout, 0.0)):
                raise LockTimeout("policy:" + tenant_id)
        if fcntl is None:  # pragma: no cover - non-POSIX platforms
            try:
                yield
            finally:
                self._write_lock.release()
            return
        fd = os.open(
            self._lock_path_for(tenant_id), os.O_RDWR | os.O_CREAT, 0o600
        )
        acquired = False
        try:
            if deadline is None:
                fcntl.flock(fd, fcntl.LOCK_EX)
            else:
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        break
                    except BlockingIOError:
                        remaining = deadline - _time.monotonic()
                        if remaining <= 0:
                            raise LockTimeout("policy:" + tenant_id)
                        _time.sleep(min(0.02, remaining))
            acquired = True
            yield
        finally:
            if acquired:
                fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)
            self._write_lock.release()

    def _write_atomic(self, path: str, payload: dict) -> None:
        fd, tmp_path = tempfile.mkstemp(dir=self.dir_path, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(payload, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.chmod(tmp_path, 0o600)
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    def _read_doc(self, path: str):
        """Return (tenant_id, rules, pending_event), or None if unreadable."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            return None
        try:
            rules = [Rule.from_json(r) for r in data["rules"]]
            return data["tenant_id"], rules, data.get("pending_event")
        except (KeyError, TypeError, ValueError, PolicyError):
            return None

    def _recover_pending_events(self) -> None:
        """Commit outbox events left pending by a crashed process."""
        try:
            names = os.listdir(self.dir_path)
        except OSError:
            return
        for name in names:
            if not name.endswith(".json") and not name.endswith(".json.del"):
                continue
            path = os.path.join(self.dir_path, name)
            doc = self._read_doc(path)
            if doc is None:
                continue
            tenant_id, rules, pending_event = doc
            if not pending_event:
                # A tombstone left behind after a successful ledger append:
                # finish the delete.
                if name.endswith(".del"):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                continue
            # A multi-file tenant restore transaction is resolved by the
            # RestoreCoordinator (its manifest drives the shared event).
            if isinstance(pending_event, dict) and pending_event.get("_restore"):
                continue
            event = AuditEvent.from_json(pending_event)
            if name.endswith(".json.del"):                # A delete tombstone. If the original file is still on disk the
                # crash happened before the unlink, so the delete never
                # happened: discard the tombstone without appending. Otherwise
                # finish the transaction (append is idempotent on event_id).
                original = path[: -len(".del")]
                if os.path.exists(original):
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                    continue
                self.audit.append(event)
                try:
                    os.unlink(path)
                except OSError:
                    pass
            else:
                # append() is idempotent on event_id.
                self.audit.append(event)
                self._write_atomic(
                    path,
                    {"tenant_id": tenant_id,
                     "rules": [r.to_json() for r in rules],
                     "pending_event": None},
                )

    def _commit_put(self, tenant_id: str, rules: List[Rule],
                    event: AuditEvent, existed: bool, previous: Optional[dict]):
        """Write a document and its event as one logical transaction."""
        path = self._path_for(tenant_id)
        doc = {
            "tenant_id": tenant_id,
            "rules": [r.to_json() for r in rules],
            "pending_event": event.to_json(),
        }
        self._write_atomic(path, doc)
        try:
            self.audit.append(event)
        except BaseException:
            if not existed:
                try:
                    os.unlink(path)
                except OSError:
                    pass
            elif previous is not None:
                self._write_atomic(path, previous)
            raise
        # The durable ledger append is the commit point; clearing the marker
        # is post-commit housekeeping. A failure here leaves the marker for
        # startup recovery and must never roll the document back or fail the
        # request.
        doc["pending_event"] = None
        try:
            self._write_atomic(path, doc)
        except OSError:
            pass

    # -- public API --------------------------------------------------------
    def get(self, tenant_id: str) -> Optional[List[Rule]]:
        """Return the tenant's rules, or None when no document exists."""
        doc = self._read_doc(self._path_for(tenant_id))
        if doc is None:
            return None
        return doc[1]

    def put(self, tenant_id: str, rules: List[Rule]) -> List[Rule]:
        """Replace (or create) the tenant's document and audit policy_update."""
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            previous = None
            if existed:
                try:
                    with open(path, "r", encoding="utf-8") as fh:
                        previous = json.load(fh)
                except (OSError, ValueError) as exc:
                    raise LedgerError(
                        "cannot read policy document: %s" % exc
                    ) from exc
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_UPDATE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            self._commit_put(tenant_id, rules, event, existed, previous)
        return rules

    def delete(self, tenant_id: str) -> None:
        """Delete the tenant's document and audit policy_delete.

        Tombstone sequence: write a ``.json.del`` marker carrying the event,
        unlink the document, append the event, then remove the marker. A crash
        between any two steps is repaired on the next open. If the ledger
        append itself fails, the original document is restored byte-for-byte
        and the tombstone discarded, so a failed delete never takes effect.
        Deleting a tenant that has no document still records the event.
        """
        with self.tenant_lock(tenant_id):
            path = self._path_for(tenant_id)
            existed = os.path.exists(path)
            event = self.audit.new_event(
                tenant_id, audit_mod.ACTION_POLICY_DELETE, None,
                audit_mod.OUTCOME_SUCCESS,
            )
            if not existed:
                self.audit.append(event)
                return
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    previous = json.load(fh)
            except (OSError, ValueError) as exc:
                raise LedgerError(
                    "cannot read policy document: %s" % exc
                ) from exc
            tombstone = path + ".del"
            self._write_atomic(
                tombstone,
                {"tenant_id": tenant_id, "rules": [],
                 "pending_event": event.to_json()},
            )
            os.unlink(path)
